    /**
     * Cadastra pagina na tabela `adms_pages` se ainda não existirem.
     *
     * Este método é executado para popular a tabela `adms_pages` com registros iniciais dos paginas.
     * Primeiro, verifica se já existe pagina na tabela com base no name. 
     * Se o pagina não existir, os dados são inseridos na tabela.
     * 
     * @return void
     */
    public function run(): void
    {
        // Variável para receber os dados a serem inseridos
        $data = [];

        // Forçar charset/collation da sessão para evitar "Illegal mix of collations"
        // quando a tabela está em utf8mb4 e a conexão padrão está em utf8/utf8mb3
        $this->execute("SET NAMES 'utf8mb4' COLLATE 'utf8mb4_unicode_ci'");
        $this->execute("SET collation_connection = 'utf8mb4_unicode_ci'");
        $this->execute("SET character_set_client = 'utf8mb4'");
        $this->execute("SET character_set_results = 'utf8mb4'");
        $this->execute("SET character_set_connection = 'utf8mb4'");

        // Garantir grupos usados com placeholder (IDs variam entre ambientes)
        $groupsToEnsure = [
            ['name' => 'Gestão de Pessoas', 'obs' => 'Módulo completo de Gestão de Pessoas (RH)'],
            ['name' => 'Reserva de Salas', 'obs' => 'Módulo de agendamento e reserva de salas de reunião'],
            ['name' => 'Comunicação Social', 'obs' => 'Timeline interna e eventos corporativos'],
            ['name' => 'Configurações', 'obs' => 'Configurações gerais do sistema'],
        ];
        foreach ($groupsToEnsure as $g) {
            $exists = $this->query('SELECT id FROM adms_groups_pages WHERE name = :name', ['name' => $g['name']])->fetch();
            if (!$exists) {
                $this->table('adms_groups_pages')->insert([
                    'name' => $g['name'],
                    'obs' => $g['obs'],
                    'created_at' => date('Y-m-d H:i:s'),
                ])->save();
            }
        }

        $configGroup = $this->query(
            "SELECT id FROM adms_groups_pages WHERE name = 'Configurações' LIMIT 1"
        )->fetch();
        $mcpGroupId = (int) ($configGroup['id'] ?? 0);
        if ($mcpGroupId <= 0) {
            $mcpGroupId = 26;
        }

