            ['name'=> 'Executar vistoria equipamento SST', 'controller' => 'SstExecuteEquipamentoVistoria', 'controller_url' => 'sst-execute-equipamento-vistoria', 'directory' => 'sst', 'obs' => 'Preencher checklist da vistoria.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
