            ['name'=> 'Cadastrar Mandato CIPA SST', 'controller' => 'SstCreateCipaMandato', 'controller_url' => 'sst-create-cipa-mandato', 'directory' => 'sst', 'obs' => 'Novo mandato CIPA.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Visualizar Mandato CIPA SST', 'controller' => 'SstViewCipaMandato', 'controller_url' => 'sst-view-cipa-mandato', 'directory' => 'sst', 'obs' => 'Membros e reuniões CIPA.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Editar Mandato CIPA SST', 'controller' => 'SstUpdateCipaMandato', 'controller_url' => 'sst-update-cipa-mandato', 'directory' => 'sst', 'obs' => 'Edição de mandato CIPA.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Excluir Mandato CIPA SST', 'controller' => 'SstDeleteCipaMandato', 'controller_url' => 'sst-delete-cipa-mandato', 'directory' => 'sst', 'obs' => 'Exclusão de mandato CIPA.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Gerenciar CIPA SST', 'controller' => 'SstManageCipa', 'controller_url' => 'sst-manage-cipa', 'directory' => 'sst', 'obs' => 'Membros e reuniões CIPA.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Listar PPP SST', 'controller' => 'SstListPpp', 'controller_url' => 'sst-list-ppp', 'directory' => 'sst', 'obs' => 'PPPs gerados.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Visualizar PPP SST', 'controller' => 'SstViewPpp', 'controller_url' => 'sst-view-ppp', 'directory' => 'sst', 'obs' => 'Detalhe do PPP gerado.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Gerar PPP SST', 'controller' => 'SstGeneratePpp', 'controller_url' => 'sst-generate-ppp', 'directory' => 'sst', 'obs' => 'Gera snapshot PPP do colaborador.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
            ['name'=> 'Exportar PPP PDF SST', 'controller' => 'SstExportPppPdf', 'controller_url' => 'sst-export-ppp-pdf', 'directory' => 'sst', 'obs' => 'Download PDF do PPP.', 'public_page' => 0, 'page_status' => 1, 'adms_packages_page_id' => 1, 'adms_groups_page_id' => 41],
        ];

        // Buscar IDs reais dos grupos pelo nome (pode ter ID diferente do esperado)
        // O auto-increment do MySQL pode pular IDs se houver exclusões ou inserções manuais
        $gestaoPessoasGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'Gestão de Pessoas'");
        if (!$gestaoPessoasGroup) {
            throw new \Exception("ERRO: O grupo 'Gestão de Pessoas' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $gestaoPessoasGroupId = (int)$gestaoPessoasGroup['id'];

        $reservaSalasGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'Reserva de Salas'");
        if (!$reservaSalasGroup) {
            throw new \Exception("ERRO: O grupo 'Reserva de Salas' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $reservaSalasGroupId = (int)$reservaSalasGroup['id'];

        $comunicacaoSocialGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'Comunicação Social'");
        if (!$comunicacaoSocialGroup) {
            throw new \Exception("ERRO: O grupo 'Comunicação Social' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $comunicacaoSocialGroupId = (int)$comunicacaoSocialGroup['id'];

        $logsGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'Logs'");
        if (!$logsGroup) {
            throw new \Exception("ERRO: O grupo 'Logs' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $logsGroupId = (int)$logsGroup['id'];

        $lgpdGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'LGPD'");
        if (!$lgpdGroup) {
            throw new \Exception("ERRO: O grupo 'LGPD' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $lgpdGroupId = (int)$lgpdGroup['id'];

        $sacGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'SAC'");
        if (!$sacGroup) {
            throw new \Exception("ERRO: O grupo 'SAC' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $sacGroupId = (int)$sacGroup['id'];

        $sstGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'Segurança e Medicina'");
        if (!$sstGroup) {
            throw new \Exception("ERRO: O grupo 'Segurança e Medicina' não foi encontrado. Execute primeiro a seed AddAdmsGroupsPages.");
        }
        $sstGroupId = (int)$sstGroup['id'];

        // Descobrir o ID real do grupo "Dashboards KPI" (criado em seeds específicas ou manualmente)
        $dashboardsKpiGroup = $this->fetchRow("SELECT id FROM adms_groups_pages WHERE name = 'Dashboards KPI'");
        $dashboardsKpiGroupId = $dashboardsKpiGroup ? (int)$dashboardsKpiGroup['id'] : null;

        // Percorrer o array com dados que devem ser validados antes de cadastrar
        foreach ($pages as $page) {
            // Verificar se o registro já existe no banco de dados (por controller_url que é único)
            $controllerUrl = $page['controller_url'];
            $existingRecord = $this->query(
                'SELECT id FROM adms_pages WHERE controller_url = :controller_url',
                ['controller_url' => $controllerUrl]
            )->fetch();

            // Se o registro não existir, insere os dados na variável $data para em seguida cadastrar na tabela
            if (!$existingRecord) {
                // Se for grupo 36 ou 37 (esperado), usar o ID real encontrado no banco
                $groupId = $page['adms_groups_page_id'];
                if ($groupId == 36) {
                    $groupId = $gestaoPessoasGroupId;
                } elseif ($groupId == 37) {
                    $groupId = $reservaSalasGroupId;
                } elseif ($groupId == 31) {
                    $groupId = $lgpdGroupId;
                } elseif ($groupId == 28) {
                    $groupId = $logsGroupId;
                } elseif ($groupId == 39) {
                    $groupId = $comunicacaoSocialGroupId;
                } elseif ($groupId == 40) {
                    $groupId = $sacGroupId;
                } elseif ($groupId == 41) {
                    $groupId = $sstGroupId;
                } elseif ($groupId == 0 && $dashboardsKpiGroupId !== null && str_contains($page['directory'], 'dashboard')) {
                    // Páginas de Dashboards KPI adicionadas nesta seed usam 0 como placeholder
                    $groupId = $dashboardsKpiGroupId;
                }
                
                // Criar o array com os dados da página
                $data[] = [
                    'name' => $page['name'],
                    'controller' => $page['controller'],
                    'controller_url' => $page['controller_url'],
                    'directory' => $page['directory'],
                    'obs' => $page['obs'],
                    'public_page' => $page['public_page'],
                    'default_page' => $page['default_page'] ?? 0,
                    'page_status' => $page['page_status'],
                    'adms_packages_page_id' => $page['adms_packages_page_id'],
                    'adms_groups_page_id' => $groupId,
                    'created_at' => date("Y-m-d H:i:s"),
                    'updated_at' => date("Y-m-d H:i:s")
                ];
            }
        }

        // Indicar em qual tabela deve salvar e inserir apenas se houver dados novos
        if (!empty($data)) {
            $adms_pages = $this->table('adms_pages');
            $adms_pages->insert($data)->save();
        }

        // Executa ajustes de ACL/default apenas quando houver novas páginas inseridas.
        // Mantém o comportamento idempotente do seed: somente pendências.
        if (!empty($data)) {
            // Blindagem para evitar "nascimento autorizado" em ambientes novos/legados:
            // - card "Meu calendário" no dashboard;
            // - páginas de Gamificação (directory = gamification);
            // - card "Quizzes (Gamificação)" no dashboard;
            // - páginas do grupo "Reserva de Salas".
            $this->execute(
                "UPDATE adms_pages
                 SET default_page = 0, updated_at = NOW()
                 WHERE controller = 'DashboardCardMyCalendar'
                   OR controller = 'DashboardCardRoomBooking'
                   OR controller = 'DashboardCardGamificationQuizzes'
                   OR directory = 'gamification'
                   OR adms_groups_page_id = {$reservaSalasGroupId}"
            );

            if ($this->hasTable('adms_access_levels_pages')) {
                $this->execute(
                    "UPDATE adms_access_levels_pages alp
                     INNER JOIN adms_pages p ON p.id = alp.adms_page_id
                     SET alp.permission = 0,
                         alp.updated_at = NOW()
                     WHERE p.public_page = 0
                       AND (p.controller = 'DashboardCardMyCalendar'
                            OR p.controller = 'DashboardCardRoomBooking'
                            OR p.controller = 'DashboardCardGamificationQuizzes'
                            OR p.directory = 'gamification'
                            OR p.adms_groups_page_id = {$reservaSalasGroupId})
                       AND NOT EXISTS (
                            SELECT 1
                            FROM (
                                SELECT adms_page_id
                                FROM adms_access_levels_pages
                                WHERE permission = 1
                            ) keep_acl
                            WHERE keep_acl.adms_page_id = p.id
                       )"
                );

                // LGPD: por padrão, páginas privadas iniciam sem permissão.
                // Exceções realmente globais permanecem públicas via public_page = 1.
                $this->execute(
                    "UPDATE adms_pages
                     SET default_page = 0, updated_at = NOW()
                     WHERE adms_groups_page_id = {$lgpdGroupId}"
                );
                $this->execute(
                    "UPDATE adms_access_levels_pages alp
                     INNER JOIN adms_pages p ON p.id = alp.adms_page_id
                     SET alp.permission = 0,
                         alp.updated_at = NOW()
                     WHERE p.adms_groups_page_id = {$lgpdGroupId}
                       AND p.public_page = 0
                       AND NOT EXISTS (
                            SELECT 1
                            FROM (
                                SELECT adms_page_id
                                FROM adms_access_levels_pages
                                WHERE permission = 1
                            ) keep_acl
                            WHERE keep_acl.adms_page_id = p.id
                       )"
                );

                // Logs: todas páginas privadas devem iniciar fechadas;
                // liberação fica a cargo do administrador por nível.
                $this->execute(
                    "UPDATE adms_pages
                     SET default_page = 0, updated_at = NOW()
                     WHERE adms_groups_page_id = {$logsGroupId}"
                );
                $this->execute(
                    "UPDATE adms_access_levels_pages alp
                     INNER JOIN adms_pages p ON p.id = alp.adms_page_id
                     SET alp.permission = 0,
                         alp.updated_at = NOW()
                     WHERE p.adms_groups_page_id = {$logsGroupId}
                       AND p.public_page = 0
                       AND NOT EXISTS (
                            SELECT 1
                            FROM (
                                SELECT adms_page_id
                                FROM adms_access_levels_pages
                                WHERE permission = 1
                            ) keep_acl
                            WHERE keep_acl.adms_page_id = p.id
                       )"
                );

                // SAC: páginas nascem sem autorização — administrador libera por nível.
                $this->execute(
                    "UPDATE adms_pages
                     SET default_page = 0, updated_at = NOW()
                     WHERE adms_groups_page_id = {$sacGroupId}"
                );
                $this->execute(
                    "UPDATE adms_access_levels_pages alp
                     INNER JOIN adms_pages p ON p.id = alp.adms_page_id
                     SET alp.permission = 0,
                         alp.updated_at = NOW()
                     WHERE p.adms_groups_page_id = {$sacGroupId}
                       AND p.public_page = 0
                       AND NOT EXISTS (
                            SELECT 1
                            FROM (
                                SELECT adms_page_id
                                FROM adms_access_levels_pages
                                WHERE permission = 1
                            ) keep_acl
                            WHERE keep_acl.adms_page_id = p.id
                       )"
                );

                // SST: páginas nascem sem autorização — administrador libera por nível.
                $this->execute(
                    "UPDATE adms_pages
                     SET default_page = 0, updated_at = NOW()
                     WHERE adms_groups_page_id = {$sstGroupId}"
                );
                $this->execute(
                    "UPDATE adms_access_levels_pages alp
                     INNER JOIN adms_pages p ON p.id = alp.adms_page_id
                     SET alp.permission = 0,
                         alp.updated_at = NOW()
                     WHERE p.adms_groups_page_id = {$sstGroupId}
                       AND p.public_page = 0
                       AND NOT EXISTS (
                            SELECT 1
                            FROM (
                                SELECT adms_page_id
                                FROM adms_access_levels_pages
                                WHERE permission = 1
                            ) keep_acl
                            WHERE keep_acl.adms_page_id = p.id
                       )"
                );
            }
        } else {
            echo "ℹ️ AddAdmsPages: sem novas páginas, hardening de ACL/default não executado.\n";
        }

        $newVersionPage = $this->query("SELECT id FROM adms_pages WHERE controller_url = 'new-training-version' LIMIT 1")->fetch();
        $updateTrainingPage = $this->query("SELECT id FROM adms_pages WHERE controller = 'UpdateTraining' LIMIT 1")->fetch();
        if ($newVersionPage && $updateTrainingPage && $this->hasTable('adms_access_levels_pages')) {
            $newVersionPageId = (int)($newVersionPage['id'] ?? 0);
            $updateTrainingPageId = (int)($updateTrainingPage['id'] ?? 0);
            if ($newVersionPageId > 0 && $updateTrainingPageId > 0) {
                $this->execute(
                    "INSERT IGNORE INTO adms_access_levels_pages (permission, adms_access_level_id, adms_page_id, created_at, updated_at)
                     SELECT alp.permission, alp.adms_access_level_id, {$newVersionPageId}, NOW(), NOW()
                     FROM adms_access_levels_pages alp
                     WHERE alp.adms_page_id = {$updateTrainingPageId}"
                );
            }
        }

        $auditPage = $this->query("SELECT id FROM adms_pages WHERE controller_url = 'training-version-audit' LIMIT 1")->fetch();
        $listTrainingsPage = $this->query("SELECT id FROM adms_pages WHERE controller = 'ListTrainings' LIMIT 1")->fetch();
        if ($auditPage && $listTrainingsPage && $this->hasTable('adms_access_levels_pages')) {
            $auditPageId = (int)($auditPage['id'] ?? 0);
            $listTrainingsPageId = (int)($listTrainingsPage['id'] ?? 0);
            if ($auditPageId > 0 && $listTrainingsPageId > 0) {
                $this->execute(
                    "INSERT IGNORE INTO adms_access_levels_pages (permission, adms_access_level_id, adms_page_id, created_at, updated_at)
                     SELECT alp.permission, alp.adms_access_level_id, {$auditPageId}, NOW(), NOW()
                     FROM adms_access_levels_pages alp
                     WHERE alp.adms_page_id = {$listTrainingsPageId}"
                );
            }
        }

        // Cisão ACL GP/SST/LGPD (idempotente; não altera permissões por page_id)
        if ($this->hasTable('adms_groups_pages') && $this->hasTable('adms_pages')) {
            require_once dirname(__DIR__) . '/helpers/AdmsPageGroupSplit.php';
            $now = date('Y-m-d H:i:s');
            AdmsPageGroupSplit::reassignPages(
                fn (string $sql) => $this->fetchRow($sql),
                fn (string $sql) => $this->fetchAll($sql),
                fn (string $sql) => $this->execute($sql),
                $now
            );
        }

        // Garantir páginas MCP no grupo Configurações (fora do CRM).
        if ($mcpGroupId > 0) {
            $mcpControllers = [
                'McpApiConfig',
                'SaveMcpApiConfig',
                'ListMcpChatTools',
                'SaveMcpChatTool',
                'McpChat',
            ];
            foreach ($mcpControllers as $ctrl) {
                $c = str_replace("'", "''", $ctrl);
                $this->execute(
                    "UPDATE adms_pages
                     SET adms_groups_page_id = {$mcpGroupId}, updated_at = NOW()
                     WHERE controller = '{$c}'"
                );
            }
        }
    }

}
